function begin(name,w=1920,h=1080){screen=name;const c=cvs(w,h);ctx=c.getContext('2d');ctx.lineCap='round';ctx.lineJoin='round';return c}
function bg(kind='world',dim=.3){const im=I[kind],s=Math.max(1920/im.width,1080/im.height);ctx.save();if(kind==='forest'){ctx.imageSmoothingEnabled=false;ctx.drawImage(im,0,0,1920,720);const tile=I.forest_ground;for(let x=0;x<1920;x+=tile.width*6)for(let y=690;y<1080;y+=tile.height*3)ctx.drawImage(tile,x,y,tile.width*6,tile.height*3);ctx.imageSmoothingEnabled=true;}else if(kind==='tavern'){ctx.filter='blur(4px)';ctx.drawImage(im,im.width*.274,im.height*.22,im.width*.487,im.height*.47,0,0,1920,1080)}else{if(dim)ctx.filter='blur(5px)';ctx.drawImage(im,(1920-im.width*s)/2,(1080-im.height*s)/2,im.width*s,im.height*s)}ctx.restore();alpha(dim,()=>rect(0,0,1920,1080,K))}
