function segments(x,y,count){for(let j=0;j<4;j++){if(j<count)piece('stamina_segment_idle',x+j*34,y,28,18);else {piece('stamina_segment_disabled',x+j*34,y,28,18);alpha(.8,()=>rect(x+j*34+3,y+3,22,12,P))}}}
function cleanSprite(im,div=1){const c=cvs(Math.round(im.width/div),Math.round(im.height/div)),g=c.getContext('2d');g.imageSmoothingEnabled=false;g.drawImage(im,0,0,c.width,c.height);const d=g.getImageData(0,0,c.width,c.height);for(let i=0;i<d.data.length;i+=4){const [r,v,b]=d.data.slice(i,i+3);if((r>170&&b>170&&v<100)||(v>150&&r<105&&b<110))d.data[i+3]=0}g.putImageData(d,0,0);return c}
