 const centers=front?{'Anselm Voigt':33,'Nell Larkin':Math.round((minX+maxX)/2),'Severa Kaltenbach':30,'Otto Grimbald':38}:{'Anselm Voigt':29,'Nell Larkin':20,'Severa Kaltenbach':39,'Otto Grimbald':36};
